"use client";

import { Textarea, type TextareaProps, type TextareaResize } from "./textarea";
import type { TextareaResizeHandles } from "./textarea";
import type { TextareaResizeHandle } from "./textarea-resizer";

export { Textarea };
export type { TextareaProps, TextareaResize, TextareaResizeHandle, TextareaResizeHandles };

"use client";

import { cva, type VariantProps } from "class-variance-authority";
import type { CSSProperties, Ref, TextareaHTMLAttributes } from "react";
import { useRef } from "react";
import { useComposedRefs } from "@/hooks/use-composed-refs";
import { inputVariants } from "@/lib/input-variants";
import { cn } from "@/lib/utils";
import { type TextareaResizeHandle, TextareaResizer } from "./textarea-resizer";
import { type TextareaResizeAxis, useTextareaResize } from "./use-textarea-resize";

const textareaVariants = cva(
  "h-auto min-w-0 resize-none overflow-x-auto overflow-y-auto scrollbar-thin [scrollbar-gutter:stable] aria-invalid:bg-[color-mix(in_oklab,var(--error)_4%,var(--background))] aria-invalid:placeholder:text-error/65",
  {
    variants: {
      size: {
        sm: "min-h-16",
        md: "min-h-20",
        lg: "min-h-24",
      },
    },
    defaultVariants: { size: "md" },
  },
);

export type TextareaResize = "none" | "vertical" | "horizontal" | "both";

/** A single handle for both edges, or one per edge. */
export type TextareaResizeHandles =
  | TextareaResizeHandle
  | { vertical?: TextareaResizeHandle; horizontal?: TextareaResizeHandle };

function resolveHandle(
  handles: TextareaResizeHandles | undefined,
  axis: TextareaResizeAxis,
): TextareaResizeHandle {
  if (handles === undefined) return "line";
  if (typeof handles === "string") return handles;
  return handles[axis] ?? "line";
}

/** Props for textarea. */
export interface TextareaProps
  extends Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, "size">,
    VariantProps<typeof inputVariants> {
  /** Ref forwarded to the underlying element. */
  ref?: Ref<HTMLTextAreaElement>;
  /** Axes exposed by the external resize handles. */
  resize?: TextareaResize;
  /** Visual form of each resize handle. */
  resizeHandle?: TextareaResizeHandles;
}

/**
 * Terminal-styled multi-line text area with directional resize handles that sit
 * outside its scroll area.
 */
export function Textarea({
  className,
  size,
  ref,
  disabled,
  readOnly,
  resize = "vertical",
  resizeHandle,
  style,
  ...props
}: TextareaProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const composedRef = useComposedRefs(textareaRef, ref);
  const { activeAxis, size: appliedSize, getAxisProps } = useTextareaResize(textareaRef, rootRef);

  const canResize = !disabled && !readOnly && resize !== "none";
  const canResizeHorizontally = canResize && (resize === "horizontal" || resize === "both");
  const canResizeVertically = canResize && (resize === "vertical" || resize === "both");
  const isResizingHorizontally = activeAxis === "horizontal" && canResizeHorizontally;
  const isResizingVertically = activeAxis === "vertical" && canResizeVertically;
  const isInvalid = props["aria-invalid"] === true || props["aria-invalid"] === "true";

  const rootStyle: CSSProperties | undefined =
    appliedSize.width === null ? undefined : { width: appliedSize.width };
  const textareaStyle: CSSProperties | undefined =
    appliedSize.height === null ? style : { ...style, height: appliedSize.height };

  return (
    <div
      data-slot="textarea-root"
      data-resize={canResize ? resize : undefined}
      className={cn(
        // Each resizable edge reserves a 16px band. The field's own border is
        // never broken and no chrome is ever painted over its content box.
        "group/textarea relative w-full min-w-0",
        canResizeVertically && "pb-4",
        canResizeHorizontally && "min-w-40 max-w-full pr-4",
        (isResizingVertically || isResizingHorizontally) && "select-none",
      )}
      ref={rootRef}
      style={rootStyle}
    >
      <textarea
        data-slot="textarea"
        className={cn(
          inputVariants({ size }),
          textareaVariants({ size }),
          disabled &&
            "disabled:bg-[color-mix(in_oklab,var(--foreground)_3%,var(--background))] disabled:text-muted-foreground disabled:opacity-100 disabled:placeholder:text-muted-foreground/50 read-only:bg-[color-mix(in_oklab,var(--foreground)_3%,var(--background))] read-only:text-muted-foreground read-only:shadow-none read-only:placeholder:text-muted-foreground/50",
          readOnly &&
            !disabled &&
            "read-only:bg-[color-mix(in_oklab,var(--foreground)_6%,var(--background))] read-only:shadow-[inset_3px_0_0_var(--border-strong)]",
          className,
        )}
        disabled={disabled}
        readOnly={readOnly}
        ref={composedRef}
        style={textareaStyle}
        {...props}
      />
      {canResizeVertically ? (
        <TextareaResizer
          axis="vertical"
          handle={resolveHandle(resizeHandle, "vertical")}
          active={isResizingVertically}
          invalid={isInvalid}
          {...getAxisProps("vertical")}
        />
      ) : null}
      {canResizeHorizontally ? (
        <TextareaResizer
          axis="horizontal"
          handle={resolveHandle(resizeHandle, "horizontal")}
          active={isResizingHorizontally}
          invalid={isInvalid}
          {...getAxisProps("horizontal")}
        />
      ) : null}
    </div>
  );
}

"use client";

import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";
import type { TextareaResizeAxis } from "./use-textarea-resize";

/**
 * Visual form of an edge handle. `line` is a short mark held off the border;
 * both `box` forms sit on the border itself, which runs unbroken behind them.
 */
export type TextareaResizeHandle = "line" | "box" | "box-label";

const AXIS_LABEL = { vertical: "vertically", horizontal: "horizontally" } as const;
const AXIS_ARROW = { vertical: "↕", horizontal: "↔" } as const;

function ResizeLine({ axis, invalid }: { axis: TextareaResizeAxis; invalid: boolean }) {
  return (
    <span
      aria-hidden="true"
      data-slot="textarea-resize-handle"
      data-handle="line"
      className={cn(
        // 30x1, centred on the edge and held 10px off the border so it reads as
        // a second mark rather than a thickening of the field's own edge.
        "pointer-events-none absolute transition-colors",
        axis === "vertical"
          ? "top-2.5 left-1/2 h-px w-[30px] -translate-x-1/2"
          : "top-1/2 left-2.5 h-[30px] w-px -translate-y-1/2",
        invalid
          ? "bg-error"
          : "bg-border group-focus-within/textarea:bg-ring group-hover/resizer:bg-foreground group-focus-visible/resizer:bg-foreground group-data-[state=active]/resizer:bg-foreground",
      )}
    />
  );
}

function ResizeBox({
  axis,
  invalid,
  label,
}: {
  axis: TextareaResizeAxis;
  invalid: boolean;
  label: boolean;
}) {
  const isVertical = axis === "vertical";

  return (
    <span
      aria-hidden="true"
      data-slot="textarea-resize-handle"
      data-handle={label ? "box-label" : "box"}
      className={cn(
        // Centred on the field's border, which stays unbroken behind it. Half of
        // the chip therefore overhangs the hit band, so it must keep its own
        // pointer events for that half to stay grabbable.
        "absolute flex items-center justify-center gap-1 border bg-background transition-colors",
        "font-mono text-[9px] leading-none tracking-wider uppercase",
        isVertical
          ? "top-0 left-1/2 -translate-x-1/2 -translate-y-1/2"
          : "top-1/2 left-0 -translate-x-1/2 -translate-y-1/2 [writing-mode:vertical-rl]",
        !label && "size-5",
        label && (isVertical ? "h-5 px-1.5" : "w-5 py-1.5"),
        invalid
          ? "border-error text-error"
          : cn(
              "border-border text-muted-foreground group-focus-within/textarea:border-ring",
              "group-hover/resizer:border-foreground group-hover/resizer:bg-foreground group-hover/resizer:text-background",
              "group-focus-visible/resizer:border-foreground group-focus-visible/resizer:bg-foreground group-focus-visible/resizer:text-background",
              "group-data-[state=active]/resizer:border-foreground group-data-[state=active]/resizer:bg-foreground group-data-[state=active]/resizer:text-background",
            ),
      )}
    >
      {/* The chip rotates on the right edge; the arrow must not, or ↔ reads as ↕. */}
      <span className={cn(!isVertical && "[writing-mode:horizontal-tb]")}>{AXIS_ARROW[axis]}</span>
      {label ? <span>resize</span> : null}
    </span>
  );
}

export interface TextareaResizerProps extends ComponentProps<"button"> {
  /** Edge this resizer drives. */
  axis: TextareaResizeAxis;
  /** Visual form of the handle. */
  handle: TextareaResizeHandle;
  /** Whether a drag is currently in progress on this axis. */
  active: boolean;
  /** Whether the field is in its error state. */
  invalid: boolean;
}

/**
 * One resizable edge: an invisible 16px hit band carrying the chosen handle.
 * The band sits entirely outside the field so it never steals a click from the
 * text or the scrollbar.
 */
export function TextareaResizer({
  axis,
  handle,
  active,
  invalid,
  className,
  ...props
}: TextareaResizerProps) {
  const isVertical = axis === "vertical";
  const accessibleLabel = `Resize textarea ${AXIS_LABEL[axis]}`;

  return (
    <button
      type="button"
      aria-label={accessibleLabel}
      title={accessibleLabel}
      data-slot="textarea-resizer"
      data-axis={axis}
      data-state={active ? "active" : undefined}
      className={cn(
        "group/resizer absolute touch-none bg-transparent focus-visible:outline-hidden",
        // When both axes resize, each band stops at the other's so they never
        // overlap and the corner stays deliberately empty.
        isVertical
          ? "inset-x-0 bottom-0 h-4 cursor-ns-resize group-data-[resize=both]/textarea:right-4"
          : "inset-y-0 right-0 w-4 cursor-ew-resize group-data-[resize=both]/textarea:bottom-4",
        className,
      )}
      {...props}
    >
      {handle === "line" ? (
        <ResizeLine axis={axis} invalid={invalid} />
      ) : (
        <ResizeBox axis={axis} invalid={invalid} label={handle === "box-label"} />
      )}
    </button>
  );
}

"use client";

import type {
  KeyboardEvent as ReactKeyboardEvent,
  MouseEvent as ReactMouseEvent,
  PointerEvent as ReactPointerEvent,
  RefObject,
} from "react";
import { useRef, useState } from "react";

/** Pixels added or removed by a single arrow-key press. */
export const RESIZE_STEP = 8;

export type TextareaResizeAxis = "vertical" | "horizontal";

interface ResizeStart {
  axis: TextareaResizeAxis;
  clientX: number;
  clientY: number;
  height: number;
  width: number;
}

interface Size {
  height: number | null;
  width: number | null;
}

// Height is the textarea's own; width belongs to the root, because the root also
// reserves the resizer band and both must grow together.
function getSizeLimits(
  textarea: HTMLTextAreaElement,
  root: HTMLDivElement,
  axis: TextareaResizeAxis,
) {
  const element = axis === "vertical" ? textarea : root;
  const styles = element.ownerDocument.defaultView?.getComputedStyle(element);
  const configuredMinimum = Number.parseFloat(
    axis === "vertical" ? (styles?.minHeight ?? "") : (styles?.minWidth ?? ""),
  );
  const maximumValue = axis === "vertical" ? styles?.maxHeight : styles?.maxWidth;
  const configuredMaximum =
    maximumValue?.endsWith("px") === true ? Number.parseFloat(maximumValue) : Number.NaN;
  const parentWidth = root.parentElement?.getBoundingClientRect().width ?? 0;
  const parentMaximum =
    axis === "horizontal" && parentWidth > 0 ? parentWidth : Number.POSITIVE_INFINITY;
  const minimum = Number.isFinite(configuredMinimum) ? configuredMinimum : 0;
  const maximum = Number.isFinite(configuredMaximum) ? configuredMaximum : Number.POSITIVE_INFINITY;

  return { minimum, maximum: Math.max(minimum, Math.min(maximum, parentMaximum)) };
}

/**
 * Pointer and keyboard resizing for the textarea's edge handles. Returns the
 * applied size plus the event handlers each axis button needs.
 */
export function useTextareaResize(
  textareaRef: RefObject<HTMLTextAreaElement | null>,
  rootRef: RefObject<HTMLDivElement | null>,
) {
  const resizeStart = useRef<ResizeStart | null>(null);
  const [size, setSize] = useState<Size>({ height: null, width: null });
  const [activeAxis, setActiveAxis] = useState<TextareaResizeAxis | null>(null);

  const readSize = (axis: TextareaResizeAxis) => {
    const textarea = textareaRef.current;
    const root = rootRef.current;
    if (!textarea || !root) return null;
    return axis === "vertical"
      ? textarea.getBoundingClientRect().height
      : root.getBoundingClientRect().width;
  };

  const setNextSize = (axis: TextareaResizeAxis, nextSize: number) => {
    const textarea = textareaRef.current;
    const root = rootRef.current;
    if (!textarea || !root) return;
    const { minimum, maximum } = getSizeLimits(textarea, root, axis);
    const clamped = Math.min(maximum, Math.max(minimum, nextSize));
    setSize((current) =>
      axis === "vertical" ? { ...current, height: clamped } : { ...current, width: clamped },
    );
  };

  const stepBy = (axis: TextareaResizeAxis, delta: number) => {
    const currentSize = readSize(axis);
    if (currentSize === null) return;
    setNextSize(axis, currentSize + delta);
  };

  const stopResizing = (event: ReactPointerEvent<HTMLButtonElement>) => {
    if (!resizeStart.current) return;
    if (event.currentTarget.hasPointerCapture?.(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
    resizeStart.current = null;
    setActiveAxis(null);
  };

  const getAxisProps = (axis: TextareaResizeAxis) => ({
    onClick: (event: ReactMouseEvent<HTMLButtonElement>) => {
      // detail 0 means the button was activated by Enter or Space, not a click.
      if (event.detail !== 0) return;
      stepBy(axis, RESIZE_STEP);
    },
    onKeyDown: (event: ReactKeyboardEvent<HTMLButtonElement>) => {
      const decreaseKey = axis === "vertical" ? "ArrowUp" : "ArrowLeft";
      const increaseKey = axis === "vertical" ? "ArrowDown" : "ArrowRight";
      if (event.key !== decreaseKey && event.key !== increaseKey) return;
      event.preventDefault();
      stepBy(axis, event.key === increaseKey ? RESIZE_STEP : -RESIZE_STEP);
    },
    onPointerDown: (event: ReactPointerEvent<HTMLButtonElement>) => {
      const textarea = textareaRef.current;
      const root = rootRef.current;
      if (!event.isPrimary || event.button !== 0 || !textarea || !root) return;
      event.preventDefault();
      event.currentTarget.focus({ preventScroll: true });
      event.currentTarget.setPointerCapture?.(event.pointerId);
      resizeStart.current = {
        axis,
        clientX: event.clientX,
        clientY: event.clientY,
        height: textarea.getBoundingClientRect().height,
        width: root.getBoundingClientRect().width,
      };
      setActiveAxis(axis);
    },
    onPointerMove: (event: ReactPointerEvent<HTMLButtonElement>) => {
      const start = resizeStart.current;
      if (!start) return;
      event.preventDefault();
      setNextSize(
        start.axis,
        start.axis === "vertical"
          ? start.height + event.clientY - start.clientY
          : start.width + event.clientX - start.clientX,
      );
    },
    onPointerUp: stopResizing,
    onPointerCancel: stopResizing,
    onLostPointerCapture: stopResizing,
  });

  return { activeAxis, size, getAxisProps };
}
